// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 newVal) public {
        c.Initialized();

        uint256 minSumAfterInit = c.MinSum();

        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == minSumAfterInit);
    }
}
